if (user.currentAction() && user.currentAction().isSkill() && user.currentAction().item().id == 19) {
    var stateList = [8, 9, 10, 11, 13, 14, 15];
    var unique = {};
    $gameTroop.aliveMembers().forEach(function(enemy) {
        stateList.forEach(function(sid) {
            if (enemy.isStateAffected(sid)) {
                unique[sid] = true;
            }
        });
    });
    var count = Object.keys(unique).length;
    if (count >= 1 && count <= 7) {
        var newStateId = 180 + count;
        $gameParty.members().forEach(function(member) {
            // Пропускаем пользователя (того, на ком висит это состояние)
            if (member === user) {
                return;
            }
            // Находим, какое из состояний 181-187 сейчас есть у персонажа
            var currentStateId = 0;
            for (var i = 181; i <= 187; i++) {
                if (member.isStateAffected(i)) {
                    currentStateId = i;
                    break;
                }
            }
            // Если текущее состояние не совпадает с нужным, заменяем
            if (currentStateId !== newStateId) {
                if (currentStateId > 0) {
                    member.removeState(currentStateId);
                }
                member.addState(newStateId);
            }
        });
        // Обновим окно статуса (чтобы изменения сразу отобразились)
        if (SceneManager._scene && SceneManager._scene._statusWindow) {
            SceneManager._scene._statusWindow.refresh();
        }
    }
}
</Custom Action End Effect>

