    for (var i = 0; i < user._enemyHpBefore.length; i++) {
        var data = user._enemyHpBefore[i];
        var enemy = data.enemy;
        var damage = data.hp - enemy.hp;
        if (damage > 0) {
            totalDamage += damage;
        }
