                user.gainHp(actualHeal);
                // Показываем зелёный попап с реально восстановленным значением
                user.startDamagePopup(actualHeal);
                // Обновляем окно статуса для отображения изменений HP
                if (SceneManager._scene && SceneManager._scene._statusWindow) {
                    SceneManager._scene._statusWindow.refresh();
                }
